#!/usr/bin/env bash
set -euo pipefail

# Put or symlink the raw MVBench dataset here. The directory should contain
# json/ and video/. MVBench.tsv is generated by VLMEvalKit and is not part of
# the raw dataset.
MV_BENCH_DATA_ROOT="${HOME}/MVBench"
HF_CACHE_ROOT="${HOME}/.cache/huggingface/hub"
MV_BENCH_CACHE_ROOT="${HF_CACHE_ROOT}/datasets--OpenGVLab--MVBench"
MV_BENCH_CACHE_REVISION="local-main"
MODEL="Qwen/Qwen2.5-VL-3B-Instruct"

if [[ ! -d "${MV_BENCH_DATA_ROOT}/json" || ! -d "${MV_BENCH_DATA_ROOT}/video" ]]; then
  echo "MVBench data not found in ${MV_BENCH_DATA_ROOT}." >&2
  echo "Please put the raw MVBench dataset there, or create a symlink:" >&2
  echo "  ln -sfn /path/to/MVBench ${MV_BENCH_DATA_ROOT}" >&2
  exit 1
fi

mkdir -p "${MV_BENCH_CACHE_ROOT}/refs" "${MV_BENCH_CACHE_ROOT}/snapshots"
ln -sfn "${MV_BENCH_DATA_ROOT}" "${MV_BENCH_CACHE_ROOT}/snapshots/${MV_BENCH_CACHE_REVISION}"
printf '%s' "${MV_BENCH_CACHE_REVISION}" > "${MV_BENCH_CACHE_ROOT}/refs/main"

CUDA_VISIBLE_DEVICES=0 \
HF_HUB_OFFLINE=1 \
LMUData="${HOME}/LMUData" \
MAX_PIXELS=1003520 \
VIDEO_MAX_PIXELS=50176 \
FPS_MAX_FRAMES=16 \
swift eval \
  --model "${MODEL}" \
  --infer_backend vllm \
  --eval_backend VLMEvalKit \
  --eval_dataset MVBench
